// ═══ DEFAULT: ForkJoinPool.commonPool() ═══
CompletableFuture.supplyAsync(() -> fetchData());
// Runs on ForkJoinPool.commonPool()
// Parallelism: Runtime.availableProcessors() - 1
// On 4-core: 3 threads. On 8-core: 7 threads.

// ═══ PROBLEMS WITH DEFAULT ═══
// 1. SHARED: parallel streams + all CF + frameworks = same 3 threads!
list.parallelStream().map(this::process);   // uses commonPool!
CompletableFuture.supplyAsync(() -> fetch()); // uses commonPool!
// Both compete for same threads!

// 2. SMALL: 3 threads for IO = disaster
for (int i = 0; i < 100; i++) {
    CompletableFuture.supplyAsync(() -> {
        httpCall();  // blocks 200ms!
    });
}
// 3 threads × 200ms = only ~15 requests/sec! Should be 500/sec!

// 3. NO CONTROL: unnamed threads, no metrics, no bounds
// Thread dump: "ForkJoinPool.commonPool-worker-1" — which task? Which service?

// ═══ FIX: DEDICATED EXECUTORS ═══
// IO pool: many threads for blocking calls
ExecutorService ioPool = new ThreadPoolExecutor(
    20, 50, 60, TimeUnit.SECONDS,
    new LinkedBlockingQueue<>(1000),
    r -> { Thread t = new Thread(r, "io-worker-" + counter.incrementAndGet());
           t.setDaemon(true); return t; },
    new ThreadPoolExecutor.CallerRunsPolicy()
);

// CPU pool: cores threads for compute
ExecutorService cpuPool = Executors.newFixedThreadPool(
    Runtime.getRuntime().availableProcessors(),
    r -> new Thread(r, "cpu-worker-" + counter.incrementAndGet())
);

// Usage:
CompletableFuture.supplyAsync(() -> httpCall(), ioPool);      // IO on dedicated pool!
CompletableFuture.supplyAsync(() -> encrypt(data), cpuPool);   // CPU on dedicated pool!
// commonPool stays free for parallel streams and framework use!

