// ─── File: src/test/java/com/bank/executor/DedicatedExecutorTest.java ───
package com.bank.executor;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class DedicatedExecutorTest {

    // ═══ Default pool size ═══
    @Test
    void defaultPool_isSmall() {
        int parallelism = ForkJoinPool.commonPool().getParallelism();
        int cores = Runtime.getRuntime().availableProcessors();
        System.out.println("Cores: " + cores + ", CommonPool parallelism: " + parallelism);
        assertThat(parallelism).isLessThanOrEqualTo(cores);
    }

    // ═══ Default pool: slow for IO-bound ═══
    @Test
    void defaultPool_slowForIO() throws Exception {
        int tasks = 20;
        long start = System.currentTimeMillis();

        List<CompletableFuture<Void>> futures = new ArrayList<>();
        for (int i = 0; i < tasks; i++) {
            futures.add(CompletableFuture.runAsync(() -> {
                try { Thread.sleep(200); } catch (InterruptedException e) { }
            }));  // default commonPool!
        }
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get();
        long elapsed = System.currentTimeMillis() - start;

        System.out.println("Default pool, 20 IO tasks: " + elapsed + "ms");
        // With 3 threads: ~1400ms (7 batches × 200ms). SLOW!
    }

    // ═══ Dedicated pool: fast for IO-bound ═══
    @Test
    void dedicatedPool_fastForIO() throws Exception {
        ExecutorService ioPool = Executors.newFixedThreadPool(20);
        int tasks = 20;
        long start = System.currentTimeMillis();

        List<CompletableFuture<Void>> futures = new ArrayList<>();
        for (int i = 0; i < tasks; i++) {
            futures.add(CompletableFuture.runAsync(() -> {
                try { Thread.sleep(200); } catch (InterruptedException e) { }
            }, ioPool));  // dedicated pool!
        }
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).get();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(elapsed).isLessThan(500);  // ~200ms! All parallel!
        ioPool.shutdown();
    }

    // ═══ Named threads for debugging ═══
    @Test
    void namedThreads_forDebugging() throws Exception {
        AtomicReference<String> threadName = new AtomicReference<>();
        ExecutorService pool = Executors.newFixedThreadPool(2, r -> {
            Thread t = new Thread(r, "payment-worker");
            return t;
        });

        CompletableFuture.supplyAsync(() -> {
            threadName.set(Thread.currentThread().getName());
            return "done";
        }, pool).get();

        assertThat(threadName.get()).isEqualTo("payment-worker");  // identifiable!
        pool.shutdown();
    }
}
